import{Handle}from"./Handle.js";class Template extends Handle{constructor(){super(),this.count=0,this.defaultTo=()=>[this]}onblamready(){this.setToFrom(),this.init()}init(){this.template=this.innerHTML,this.innerHTML=""}interpolate(template,data){let interpolated=template.replace(/\[\[(.*?)\]\]/g,(_,prop)=>isNaN(data[prop])?data[prop]:parseFloat(data[prop]).toFixed(this.places));this.additive?(this.count>=this.max&&(this.toElems[0].innerHTML="",this.count=0),this.toElems[0].innerHTML+=interpolated):this.toElems[0].innerHTML=interpolated,this.additive&&this.count++}get additive(){return this.hasAttribute("additive")}set additive(value){this.toBoolean("additive",value)}get max(){return this.getAttribute("max")||16}set max(value){this.setAttribute("max",value)}get places(){return this.getAttribute("places")||1}set places(value){this.setAttribute("places",value)}}export{Template};